{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Topiramate, a highly oxygenated non-ionizable small molecule, has oral bioavailability >80% in healthy volunteers, supporting that a polyoxygenated scaffold without ionizable groups can achieve F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Methylprednisolone, a polycyclic oxygenated corticosteroid, has absolute oral bioavailability of about 72.6% after oral solution versus IV, indicating that fused-ring oxygenated natural-product-like molecules can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Hydrocortisone, another polycyclic oxygenated steroid, shows absolute oral bioavailability of about 95.9% in healthy subjects, reinforcing high oral bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Oridonin, a diterpenoid natural product with poor water solubility, is reported to have low oral bioavailability in humans, which is a caution for the query's diterpenoid-like scaffold; however, the low Morgan similarity and lack of a numeric F value limit its transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is predicted high (F >= 20%). Consistent high-bioavailability evidence from oxygenated polycyclic and non-ionizable small molecules outweighs the single low-bioavailability diterpenoid analogue, but confidence is low because all retrieved analogues have low Morgan similarity and the low-F evidence is non-quantitative.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value for the query or a close analogue is available in the supplied evidence.",
    "The oridonin low-bioavailability record lacks a numeric F value, so it cannot be confirmed to be below the 20% threshold.",
    "All Morgan similarity scores are below 0.25, limiting structural transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

